<script setup lang="ts">
/**
 * A scrolling conversation log that follows the newest turn (`design/components/chat-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import { agentMember, followEnd, jumpToEnd, slotted } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/chat-thread.module.css'
import Button from '../controls/Button.vue'

export interface ChatThreadMessages {
  jumpToLatest: string
}

export interface ChatThreadProps {
  /**
   * The log's accessible name, such as "Conversation" in the app's language.
   */
  label: string
  /**
   * The thread's only built-in text (generic English default), which localized hosts replace.
   */
  messages?: ChatThreadMessages
  /**
   * Whether a reply is arriving, which sets `aria-busy` on the log.
   */
  streaming?: boolean
}

defineOptions({ name: 'ChatThread', inheritAttrs: false })

const props = withDefaults(defineProps<ChatThreadProps>(), {
  messages: () => ({ jumpToLatest: 'Jump to latest' }),
  streaming: false,
})
defineSlots<{
  default?: (props: Record<string, never>) => unknown
  empty?: (props: Record<string, never>) => unknown
}>()
const detached = ref(false)
const overflowing = ref(false)
const jump = useTemplateRef<HTMLElement>('jump')
const list = useTemplateRef<HTMLElement>('list')
const viewport = useTemplateRef<HTMLElement>('viewport')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = followEnd(viewport.value, list.value, (state) => {
    detached.value = state.detached
    overflowing.value = state.overflowing
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
watch(() => list.value, effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'ChatThread',
    element: () => viewport.value,
    state: () => ({ streaming: props.streaming }),
    actions: {},
    withholds: () => jump.value,
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    :class="styles.root"
    :data-state="detached ? 'detached' : undefined"
    :data-streaming="streaming ? '' : undefined"
    data-member="chat-thread"
  >
    <!-- viewport -->
    <div
      ref="viewport"
      :class="styles.viewport"
      data-chat-thread-part="viewport"
      role="log"
      :aria-label="label"
      aria-relevant="additions"
      :aria-busy="streaming ? true : undefined"
      :tabindex="overflowing ? '0' : undefined"
    >
      <!-- empty -->
      <div v-if="slotted($slots.default).count === 0" :class="styles.empty">
        <slot name="empty" />
      </div>
      <!-- list -->
      <div v-else ref="list" :class="styles.list">
        <slot />
      </div>
    </div>
    <!-- jump -->
    <div ref="jump" :class="styles.jump">
      <Button
        variant="outline"
        tone="neutral"
        size="sm"
        icon="down"
        :label="messages.jumpToLatest"
        @click="jumpToEnd(viewport)"
      />
    </div>
  </div>
</template>
